def estimate_stall_risk(bitrate_mbps: float, bandwidth_mbps: float, buffer_sec: float) -> str:
    if bandwidth_mbps < bitrate_mbps and buffer_sec < 4.0:
        return 'REBUFFER_IMMINENT'
    return 'STABLE'

def validate_closed_gop(segment_starts_with_idr: bool, duration_sec: float) -> None:
    if not segment_starts_with_idr:
        raise ValueError('Segment must begin with an IDR keyframe for clean ABR switching')
    if not (1.0 <= duration_sec <= 6.0):
        raise ValueError('Segment duration outside 1-6s ABR target')

def build_transcode_dag(chunks: list[str], rungs: list[str]) -> list[dict]:
    tasks = []
    for chunk_id in chunks:
        for rung in rungs:
            tasks.append({'chunk_id': chunk_id, 'rung': rung, 'codec': 'h264_nvenc'})
    return tasks

def generate_hls_master(variants: list[dict]) -> str:
    lines = ['#EXTM3U', '#EXT-X-VERSION:6']
    for v in variants:
        lines.append(f"#EXT-X-STREAM-INF:BANDWIDTH={v['bps']},RESOLUTION={v['res']},CODECS=\"{v['codec']}\"")
        lines.append(v['playlist_url'])
    return '\n'.join(lines)

def choose_next_rung(rungs: list[dict], est_bps: float, buffer_sec: float) -> dict:
    safe_bps = est_bps * (0.65 if buffer_sec < 8.0 else 0.85)
    eligible = [r for r in rungs if r['bps'] <= safe_bps]
    return max(eligible, key=lambda r: r['bps']) if eligible else min(rungs, key=lambda r: r['bps'])

def issue_drm_license(auth_svc, kms, user_id: str, title_id: str, drm_system: str) -> bytes:
    if not auth_svc.has_entitlement(user_id, title_id):
        raise PermissionError('User not entitled to stream title')
    content_key = kms.get_title_dek(title_id)
    return kms.wrap_license_response(content_key, drm_system)

def select_convex_hull_rungs(candidates: list[dict], min_vmaf: float = 93.0) -> list[dict]:
    pareto = [c for c in candidates if c['vmaf'] >= min_vmaf]
    return sorted(pareto, key=lambda c: c['bps'])[:1] or [max(candidates, key=lambda c: c['vmaf'])]
